    val Pilcrow by lazy { lucide("Pilcrow", "M13 4v16", "M17 4v16", "M19 4H9.5a4.5 4.5 0 0 0 0 9H13") }
    val IndentIncrease by lazy { lucide("IndentIncrease", "M21 5H11", "M21 12H11", "M21 19H11", "m3 8 4 4-4 4") }
    val IndentDecrease by lazy { lucide("IndentDecrease", "M21 5H11", "M21 12H11", "M21 19H11", "m7 8-4 4 4 4") }
    val Circle by lazy { lucide("Circle", "M2 12a10 10 0 1 0 20 0a10 10 0 1 0 -20 0") }
    val Text by lazy { lucide("Text", "M21 5H3", "M15 12H3", "M17 19H3") }
    val CircleAlert by lazy { lucide("CircleAlert", "M2 12a10 10 0 1 0 20 0a10 10 0 1 0 -20 0", "M12 8L12 12", "M12 16L12.01 16") }
    val Key by lazy { lucide("Key", "m2 21 9.6-9.6", "m7.5 15.5 2.3 2.3a1 1 0 0 1 0 1.4l-2.1 2.1a1 1 0 0 1-1.4 0L4 19", "M10 7.5a5.5 5.5 0 1 0 11 0a5.5 5.5 0 1 0 -11 0") }
}

private fun lucide(name: String, vararg paths: String): ImageVector =
    ImageVector.Builder(name, 24.dp, 24.dp, 24f, 24f).apply {
        for (path in paths) addPath(
            PathParser().parsePathString(path).toNodes(),
            stroke = SolidColor(Color.Black),
            strokeLineWidth = 2f,
            strokeLineCap = StrokeCap.Round,
            strokeLineJoin = StrokeJoin.Round,
        )
    }.build()
